"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { MenuIcon } from "lucide-react";
import { CrestLogo, WorldSkillsLogo } from "@/components/brand/LogoMark";
import { useAuth } from "@/components/auth/AuthProvider";
import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import {
  homeForRole,
  isAdminRole,
  isCompetitorRole,
  isExpertRole,
  isInstitutionRole,
} from "@/lib/api";
import { cn } from "@/lib/utils";

type NavItem = { href: string; label: string };

function roleLabel(role: string): string {
  if (isAdminRole(role)) return "Administrator";
  if (isInstitutionRole(role)) return "Institution";
  if (isCompetitorRole(role)) return "Competitor";
  if (isExpertRole(role)) return "Assessor";
  return role;
}

export function SiteHeader() {
  const pathname = usePathname();
  const { status, me, logout, requireRole } = useAuth();

  const navItems: NavItem[] = [{ href: "/", label: "Home" }];

  if (status === "authenticated" && me) {
    if (requireRole("admin")) {
      navItems.push({ href: "/admin", label: "Admin" });
    }
    if (requireRole("institution")) {
      navItems.push({ href: "/institution", label: "School portal" });
    }
    if (requireRole("competitor")) {
      navItems.push({ href: "/competitor", label: "My registration" });
    }
    if (requireRole("expert")) {
      navItems.push({ href: "/expert", label: "Assessor" });
    }
  }

  const portalHref =
    status === "authenticated" && me ? homeForRole(me.role) : "/login";

  function isActive(href: string) {
    if (href === "/") return pathname === "/";
    return pathname === href || pathname.startsWith(`${href}/`);
  }

  return (
    <header className="sticky top-0 z-50 border-b border-border/80 bg-background/95 backdrop-blur-md">
      <div className="mx-auto flex max-w-6xl items-center justify-between gap-3 px-4 py-3 sm:gap-4 sm:px-6">
        <Link
          href="/"
          className="flex min-w-0 items-center gap-2.5 sm:gap-3"
          aria-label="WorldSkills Ghana home"
        >
          <CrestLogo className="h-10 w-auto shrink-0 object-contain sm:h-12" priority />
          <WorldSkillsLogo className="hidden h-9 w-auto max-w-[9.5rem] object-contain object-left sm:block md:max-w-[11rem]" />
          <span className="truncate text-sm font-bold tracking-tight text-foreground sm:hidden">
            WorldSkills Ghana
          </span>
        </Link>

        <nav className="hidden items-center gap-1 md:flex" aria-label="Main">
          {navItems.map((item) => {
            const active = isActive(item.href);
            return (
              <Button
                key={item.href}
                variant="ghost"
                size="sm"
                className={cn(
                  active &&
                    "bg-primary/10 font-semibold text-primary hover:bg-primary/15 hover:text-primary",
                )}
                asChild
              >
                <Link href={item.href} aria-current={active ? "page" : undefined}>
                  {item.label}
                </Link>
              </Button>
            );
          })}
          {status === "authenticated" && me ? (
            <span className="ml-2 hidden max-w-[10rem] truncate text-xs text-muted-foreground lg:inline">
              {me.full_name ?? me.email}
              <span className="text-border"> · </span>
              {roleLabel(me.role)}
            </span>
          ) : null}
          {status === "authenticated" ? (
            <Button variant="outline" size="default" className="ml-1" onClick={logout}>
              Sign out
            </Button>
          ) : (
            <Button variant="accent" size="default" className="ml-1" asChild>
              <Link href="/login">Enter portal</Link>
            </Button>
          )}
        </nav>

        <Sheet>
          <SheetTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="min-h-11 min-w-11 md:hidden"
              aria-label="Open menu"
            >
              <MenuIcon />
            </Button>
          </SheetTrigger>
          <SheetContent side="right" className="w-[min(100%,20rem)] px-4">
            <SheetHeader className="text-left">
              <SheetTitle>Menu</SheetTitle>
            </SheetHeader>
            {status === "authenticated" && me ? (
              <p className="mt-1 px-1 text-xs text-muted-foreground">
                Signed in as {roleLabel(me.role)}
              </p>
            ) : null}
            <nav className="mt-4 flex flex-col gap-1" aria-label="Mobile">
              {navItems.map((item) => {
                const active = isActive(item.href);
                return (
                  <SheetClose key={item.href} asChild>
                    <Button
                      variant="ghost"
                      className={cn(
                        "min-h-11 justify-start px-3",
                        active && "bg-primary/10 font-semibold text-primary",
                      )}
                      asChild
                    >
                      <Link
                        href={item.href}
                        aria-current={active ? "page" : undefined}
                      >
                        {item.label}
                      </Link>
                    </Button>
                  </SheetClose>
                );
              })}
              {status === "authenticated" && me ? (
                <SheetClose asChild>
                  <Button
                    variant="ghost"
                    className="min-h-11 justify-start px-3"
                    asChild
                  >
                    <Link href={portalHref}>
                      {isAdminRole(me.role)
                        ? "Administration"
                        : isInstitutionRole(me.role)
                          ? "Institution portal"
                          : isCompetitorRole(me.role)
                            ? "Competitor portal"
                            : isExpertRole(me.role)
                              ? "Assessor portal"
                              : "Enter portal"}
                    </Link>
                  </Button>
                </SheetClose>
              ) : null}
              {status === "authenticated" ? (
                <Button
                  variant="outline"
                  className="mt-4 min-h-11 w-full"
                  onClick={logout}
                >
                  Sign out
                </Button>
              ) : (
                <SheetClose asChild>
                  <Button variant="accent" className="mt-4 min-h-11 w-full" asChild>
                    <Link href="/login">Enter portal</Link>
                  </Button>
                </SheetClose>
              )}
            </nav>
          </SheetContent>
        </Sheet>
      </div>
      <div
        className="h-0.5 bg-gradient-to-r from-brand-blue via-brand-gold to-brand-red"
        aria-hidden
      />
    </header>
  );
}
